{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C50"],
      "claim": "Pethidine absolute oral bioavailability was 0.80 ± 0.15 in patients with cirrhosis, well above the 20% threshold, and the high transfer score supports a high-F expectation for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C67"],
      "claim": "Ampicillin oral bioavailability was 41% in young subjects, clearly above the 20% threshold, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C54"],
      "claim": "Atazanavir absolute oral bioavailability in humans is 68% (57–80%), well above the threshold, supporting a high-F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Phenoxymethylpenicillin oral bioavailability was 54.8% in normal children, above the 20% threshold and consistent with high oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C66"],
      "claim": "Isoniazid oral bioavailability was 91.4% in patients, strongly above the threshold and supportive of high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Fenspiride absolute oral bioavailability was 90% in healthy volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C84"],
      "claim": "Vorinostat absolute oral bioavailability is 43% in humans, above the 20% threshold despite being described as suboptimal in a relative sense.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C74"],
      "claim": "Safinamide has a high absolute oral bioavailability of 95% in humans, strongly supporting a high-F outcome.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C73"],
      "claim": "Quinapril absolute oral bioavailability was 51.7% in healthy participants, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "One labetalol record reports 18% oral bioavailability, below the 20% threshold, but this is an outlier relative to other labetalol measurements (20–38%) and is outweighed by the consistent high-F evidence from other high-transfer analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental evidence points to oral bioavailability well above 20%, with most measured values between 40% and 95%. The single sub-20% labetalol value is an isolated outlier. The query's small, neutral amide/nitroimidazole structure is consistent with good oral absorption, so F >= 20% is strongly supported.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule itself.",
    "No nitroimidazole-containing analogue is present among the retrieved evidence; all evidence comes from structurally diverse drugs, though transfer scores are uniformly high."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

